import { useMemo } from 'react';
import { useSiteRoster } from '../../data/use-site-roster.js';
import { useThreadsEnabled } from './enabled.js';
import { mentionCandidates } from './mentions.js';
const NO_CANDIDATES = Object.freeze([]);
export function useSiteMembers(wanted) {
    const enabled = useThreadsEnabled();
    const { roster, loading } = useSiteRoster(enabled && wanted);
    const candidates = useMemo(() => (roster ? mentionCandidates(roster) : NO_CANDIDATES), [roster]);
    return { candidates, loading };
}
