const eventListeners = new Set();
const reconnectListeners = new Set();
export function subscribeToThreadEvents(onEvent) {
    eventListeners.add(onEvent);
    return () => {
        eventListeners.delete(onEvent);
    };
}
export function publishThreadEvent(event) {
    eventListeners.forEach((onEvent) => onEvent(event));
}
export function subscribeToThreadsReconnect(onReconnect) {
    reconnectListeners.add(onReconnect);
    return () => {
        reconnectListeners.delete(onReconnect);
    };
}
export function publishThreadsReconnect() {
    reconnectListeners.forEach((onReconnect) => onReconnect());
}
