import { useCallback, useEffect, useState } from 'react';
import { aiPanelStore } from './aiPanelStore.js';
const ESCAPE_OWNER_SELECTOR = [
    '[aria-modal="true"]',
    '[role="dialog"]',
    '[role="menu"]',
    '[role="listbox"]',
    '[aria-haspopup][aria-expanded="true"]',
].join(', ');
function isPopupOpen() {
    return document.querySelector(ESCAPE_OWNER_SELECTOR) !== null;
}
function canvasWindow() {
    const iframe = document.getElementById('preview-frame');
    return iframe instanceof HTMLIFrameElement ? iframe.contentWindow : null;
}
function listen(target, handler) {
    try {
        target.addEventListener('keydown', handler, { capture: true });
    }
    catch {
        return null;
    }
    return () => {
        try {
            target.removeEventListener('keydown', handler, { capture: true });
        }
        catch {
        }
    };
}
export function useFocusMode() {
    const [on, setOn] = useState(false);
    const toggle = useCallback(() => {
        setOn((prev) => !prev);
    }, []);
    useEffect(() => {
        if (!on)
            return;
        const handleKeyDown = (event) => {
            if (event.key !== 'Escape' || event.defaultPrevented || isPopupOpen())
                return;
            setOn(false);
        };
        const unlisteners = [window, canvasWindow()]
            .map((target) => (target ? listen(target, handleKeyDown) : null))
            .filter((unlisten) => unlisten !== null);
        return () => {
            for (const unlisten of unlisteners)
                unlisten();
        };
    }, [on]);
    useEffect(() => {
        if (!on)
            return;
        return aiPanelStore.subscribe(() => {
            setOn(false);
            if (!aiPanelStore.isOpen())
                aiPanelStore.open();
        });
    }, [on]);
    return [on, toggle];
}
