import { useSyncExternalStore } from 'react';
const listeners = new Set();
let enabled = false;
export function subscribeToThreadsEnabled(onChange) {
    listeners.add(onChange);
    return () => {
        listeners.delete(onChange);
    };
}
export function getThreadsEnabled() {
    return enabled;
}
export function setThreadsEnabled(next) {
    if (next === enabled)
        return;
    enabled = next;
    listeners.forEach((onChange) => onChange());
}
export function useThreadsEnabled() {
    return useSyncExternalStore(subscribeToThreadsEnabled, getThreadsEnabled, getThreadsEnabled);
}
