import { useContext } from 'react';
import { QueryClient, useQuery } from '@tanstack/react-query';
import { useP1PuckOptional } from '../core/P1PuckContext.js';
import { P1SdkQueryClientContext } from './query-provider.js';
export const SITE_MEMBERS_KEY = 'p1-site-members';
const NO_SDK_CLIENT = new QueryClient();
export function siteMembersKey(siteId) {
    return [SITE_MEMBERS_KEY, siteId];
}
export function useSiteRoster(wanted) {
    const ccr = useP1PuckOptional();
    const sdkClient = useContext(P1SdkQueryClientContext);
    const ready = wanted && Boolean(sdkClient && ccr?.siteId);
    const { data, isPending } = useQuery({
        queryKey: siteMembersKey(ccr?.siteId),
        queryFn: ccr ? () => ccr.client.sites.members(ccr.siteId) : undefined,
        enabled: ready,
    }, sdkClient ?? NO_SDK_CLIENT);
    if (!ready)
        return { roster: undefined, loading: false };
    return { roster: data, loading: isPending };
}
