import { diffPuckDataWithPositions } from '../versioning/utils/diff.js';
import { deepEqual } from '../merge/utils/puckFieldClassifier.js';
export const RAIL_STATUS_LABEL = {
    conflict: 'Conflict',
    resolved: 'Resolved',
    changed: 'Changed',
    added: 'Added',
    deleted: 'Deleted',
};
const METADATA_KEYS = ['title', 'description', 'slug'];
export function metadataDiffers(a, b) {
    if (a === null || b === null)
        return a !== b;
    const aRoot = a.root?.props ?? {};
    const bRoot = b.root?.props ?? {};
    for (const key of METADATA_KEYS) {
        if (!deepEqual(aRoot[key], bRoot[key]))
            return true;
    }
    const aMeta = (aRoot['_meta'] ?? {});
    const bMeta = (bRoot['_meta'] ?? {});
    const metaKeys = new Set([...Object.keys(aMeta), ...Object.keys(bMeta)]);
    for (const key of metaKeys) {
        if (!deepEqual(aMeta[key], bMeta[key]))
            return true;
    }
    return false;
}
export function localeDiffers(doc) {
    if (doc.changeType === 'deleted-on-draft' || doc.changeType === 'deleted-on-main')
        return false;
    return (doc.sourceLocale ?? null) !== (doc.targetLocale ?? null);
}
function resolveStatus(doc, strategy = doc.strategy) {
    const { changeType } = doc;
    if (changeType === 'new-on-draft')
        return 'added';
    if (changeType === 'deleted-on-draft')
        return 'deleted';
    if (changeType === 'conflicting' || changeType === 'deleted-on-main') {
        return strategy === 'unresolved' ? 'conflict' : 'resolved';
    }
    return 'changed';
}
export function resolveTitle(doc) {
    const path = doc.documentPath.replace(/^\//, '');
    return path === '' ? 'Homepage' : path;
}
const diffCache = new WeakMap();
function hasContentDiffCached(source, target) {
    let bySource = diffCache.get(source);
    const cached = bySource?.get(target);
    if (cached !== undefined)
        return cached;
    const result = diffPuckDataWithPositions(target, source).some((d) => d.type !== 'unchanged');
    if (!bySource) {
        bySource = new WeakMap();
        diffCache.set(source, bySource);
    }
    bySource.set(target, result);
    return result;
}
export function toRailItems(doc) {
    const { documentId, documentPath, sourceSnapshot, targetSnapshot } = doc;
    const status = resolveStatus(doc, doc.aspects?.content);
    const metadataStatus = resolveStatus(doc, doc.aspects?.metadata);
    const pageTitle = resolveTitle(doc);
    const items = [];
    const hasContentDiff = sourceSnapshot === null || targetSnapshot === null
        ? sourceSnapshot !== targetSnapshot
        : hasContentDiffCached(sourceSnapshot, targetSnapshot);
    if (hasContentDiff) {
        items.push({ id: `${documentId}:content`, documentId, kind: 'content', pageTitle, path: documentPath, status });
    }
    if (metadataDiffers(sourceSnapshot, targetSnapshot) || localeDiffers(doc)) {
        items.push({ id: `${documentId}:metadata`, documentId, kind: 'metadata', pageTitle, path: documentPath, status: metadataStatus });
    }
    if (items.length === 0) {
        items.push({ id: `${documentId}:content`, documentId, kind: 'content', pageTitle, path: documentPath, status });
    }
    return items;
}
export function hasSplitMetadata(doc) {
    return doc.changeType === 'conflicting' && !!doc.sourceSnapshot && !!doc.targetSnapshot && toRailItems(doc).length === 2;
}
export function groupRailItems(docs) {
    const sorted = [...docs].sort((a, b) => {
        const aConflict = resolveStatus(a) === 'conflict' ? 0 : 1;
        const bConflict = resolveStatus(b) === 'conflict' ? 0 : 1;
        if (aConflict !== bConflict)
            return aConflict - bConflict;
        return a.documentPath.localeCompare(b.documentPath);
    });
    return sorted
        .map((doc) => ({
        documentId: doc.documentId,
        pageTitle: resolveTitle(doc),
        path: doc.documentPath,
        items: toRailItems(doc),
    }));
}
export function nextUnresolvedIndex(groups, fromId) {
    const flat = groups.flatMap((g) => g.items);
    const startIdx = fromId
        ? flat.findIndex((i) => i.id === fromId)
        : -1;
    for (let offset = 1; offset <= flat.length; offset++) {
        const idx = (startIdx + offset) % flat.length;
        if (flat[idx]?.status === 'conflict')
            return idx;
    }
    return -1;
}
