function hasStatus(err, status) {
    return err instanceof Error && "status" in err && err.status === status;
}
export function isDocumentGoneError(err) {
    return hasStatus(err, 410);
}
export function isNotFoundStatus(err) {
    return hasStatus(err, 404);
}
export class DocumentPathNotFoundError extends Error {
    path;
    name = "DocumentPathNotFoundError";
    constructor(path) {
        super(`No document at path: ${path}`);
        this.path = path;
        Object.setPrototypeOf(this, DocumentPathNotFoundError.prototype);
    }
}
export function isDocumentNotFoundError(err) {
    return err instanceof DocumentPathNotFoundError;
}
export function rawValueToString(value) {
    if (value == null)
        return "";
    if (typeof value === "string")
        return value;
    if (typeof value === "number" || typeof value === "boolean")
        return String(value);
    return "";
}
