import { iconList } from '@pantheon-systems/pds-toolkit-react';
const AVAILABLE = new Set(Array.isArray(iconList) ? iconList : []);
const FALLBACK = ['squareDashed', 'squareMinus'];
const BY_KEYWORD = [
    ['image', ['image']],
    ['photo', ['image']],
    ['video', ['video']],
    ['media', ['image']],
    ['heading', ['text']],
    ['title', ['text']],
    ['paragraph', ['memo']],
    ['text', ['text']],
    ['quote', ['quotesLeft']],
    ['list', ['rectangleList']],
    ['table', ['table']],
    ['grid', ['grid']],
    ['divider', ['minus']],
    ['spacer', ['expand']],
    ['button', ['link', 'linkSimple']],
    ['link', ['link', 'linkSimple']],
    ['card', FALLBACK],
    ['code', ['code']],
    ['form', ['inputText']],
    ['hero', ['billboard']],
    ['banner', ['billboard']],
    ['footer', ['sitemap']],
    ['header', ['sitemap']],
    ['welcome', ['house']],
];
function firstAvailable(candidates) {
    if (AVAILABLE.size === 0)
        return candidates[0] ?? null;
    return candidates.find((name) => AVAILABLE.has(name)) ?? null;
}
function tokenize(s) {
    return [
        ...new Set(s
            .replace(/([a-z])([A-Z])/g, '$1 $2')
            .split(/[^a-zA-Z]+/)
            .map((t) => t.toLowerCase())
            .filter(Boolean)),
    ];
}
export function getIconForComponent(type, label) {
    const tokens = new Set([...tokenize(type), ...(label ? tokenize(label) : [])]);
    for (const [keyword, candidates] of BY_KEYWORD) {
        if (tokens.has(keyword))
            return firstAvailable(candidates);
    }
    return firstAvailable(FALLBACK);
}
