export const THREAD_COMMENTS_KEY = 'p1-thread-comments';
export const NO_COMMENTS = Object.freeze([]);
export function threadCommentsKey(siteId, threadId) {
    return [THREAD_COMMENTS_KEY, siteId, threadId];
}
export function insertComment(comments, comment) {
    const at = comments.findIndex((c) => c.id === comment.id);
    if (at === -1)
        return insertNew(comments, comment);
    if (comments[at] === comment)
        return comments;
    return comments.map((c) => (c.id === comment.id ? comment : c));
}
function insertNew(comments, comment) {
    const at = comments.findIndex((c) => c.createdAt > comment.createdAt);
    if (at === -1)
        return [...comments, comment];
    return [...comments.slice(0, at), comment, ...comments.slice(at)];
}
export function storeThread(queryClient, thread) {
    queryClient.setQueryData(threadCommentsKey(thread.thread.siteId, thread.thread.id), thread);
}
export function appendThreadComment(queryClient, siteId, comment) {
    const key = threadCommentsKey(siteId, comment.threadId);
    const loaded = queryClient.getQueryData(key);
    if (loaded === undefined)
        return false;
    const comments = insertComment(loaded.comments, comment);
    if (comments === loaded.comments)
        return true;
    queryClient.setQueryData(key, { ...loaded, comments: [...comments] });
    return true;
}
